head.script:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://ratescout.ru/#website",
      "url": "https://ratescout.ru/en/",
      "name": "RateScout",
      "description": "Free directory of crypto and cash exchange rates based on BestChange monitoring data.",
      "inLanguage": ["en","es","fr","ru"]
    },
    {
      "@type": "Organization",
      "@id": "https://ratescout.ru/#org",
      "name": "RateScout",
      "url": "https://ratescout.ru/en/",
      "logo": "https://ratescout.ru/logo.png"
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {"@type":"Question","name":"Is RateScout really free?","acceptedAnswer":{"@type":"Answer","text":"Yes. The directory is free to browse, with no account and no commission on the rates shown."}},
        {"@type":"Question","name":"Where do the rates come from?","acceptedAnswer":{"@type":"Answer","text":"They are based on BestChange exchange-monitoring data. See the methodology page for details."}},
        {"@type":"Question","name":"Are these binding offers?","acceptedAnswer":{"@type":"Answer","text":"No. Rates are provided for reference only and can change at any time. Always confirm with the exchanger."}},
        {"@type":"Question","name":"How often do rates update?","acceptedAnswer":{"@type":"Answer","text":"Every hour. The timestamp at the top of the page shows the last sync."}}
      ]
    }
  ]
}

head.b:skin:
:root{
  --bg:#0b0f17; --bg-soft:#121826; --card:#161d2d; --border:#232c40;
  --text:#e8ecf4; --muted:#8a95ab; --accent:#00d18f; --accent-2:#3b82f6;
  --radius:14px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Inter,Arial,sans-serif;
  background:var(--bg);color:var(--text);line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
a{color:inherit;text-decoration:none}
.wrap{max-width:1140px;margin:0 auto;padding:0 20px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}

/* HEADER */
header{position:sticky;top:0;z-index:50;background:rgba(11,15,23,.85);
  backdrop-filter:blur(12px);border-bottom:1px solid var(--border)}
.nav{display:flex;align-items:center;justify-content:space-between;height:68px;gap:16px}
.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:18px;letter-spacing:-.3px}
.logo-mark{width:32px;height:32px;border-radius:9px;
  background:linear-gradient(135deg,var(--accent),var(--accent-2));
  display:grid;place-items:center;font-size:15px;font-weight:800;color:#04110c}
.nav-links{display:flex;gap:26px;font-size:14px;color:var(--muted)}
.nav-links a:hover{color:var(--text)}
.nav-right{display:flex;align-items:center;gap:14px}

/* LANG SWITCH */
.lang{position:relative}
.lang-btn{
  display:flex;align-items:center;gap:6px;padding:8px 12px;border-radius:9px;
  background:var(--bg-soft);border:1px solid var(--border);color:var(--text);
  font-size:13.5px;font-weight:600;cursor:pointer;transition:.2s
}
.lang-btn:hover{border-color:var(--muted)}
.lang-menu{
  position:absolute;right:0;top:calc(100% + 8px);min-width:170px;
  background:var(--card);border:1px solid var(--border);border-radius:11px;
  padding:6px;display:none;flex-direction:column;gap:2px;
  box-shadow:0 20px 40px rgba(0,0,0,.5);z-index:60
}
.lang.open .lang-menu{display:flex}
.lang-menu button{
  display:flex;align-items:center;gap:10px;width:100%;text-align:left;
  padding:9px 11px;border-radius:8px;background:none;border:0;
  color:var(--text);font-size:14px;cursor:pointer;transition:.15s
}
.lang-menu button:hover{background:var(--bg-soft)}
.lang-menu button[aria-current="true"]{color:var(--accent);font-weight:600}
.flag{font-size:15px}

.nav-cta{padding:9px 18px;border-radius:9px;font-size:14px;font-weight:600;
  background:var(--accent);color:#04110c;transition:.2s;white-space:nowrap}
.nav-cta:hover{filter:brightness(1.1)}
@media(max-width:900px){.nav-links{display:none}}

/* HERO */
.hero{padding:90px 0 70px;text-align:center;position:relative;overflow:hidden}
.hero::before{content:"";position:absolute;top:-200px;left:50%;transform:translateX(-50%);
  width:700px;height:700px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,209,143,.14),transparent 65%);pointer-events:none}
.badge{display:inline-flex;align-items:center;gap:8px;padding:6px 14px;
  border-radius:100px;font-size:13px;background:var(--bg-soft);
  border:1px solid var(--border);color:var(--muted);margin-bottom:26px;position:relative}
.dot{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 8px var(--accent)}
h1{font-size:clamp(34px,5.5vw,58px);line-height:1.1;letter-spacing:-1.5px;
  font-weight:800;margin-bottom:22px;position:relative}
h1 span{background:linear-gradient(120deg,var(--accent),var(--accent-2));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.hero p{font-size:clamp(16px,2vw,19px);color:var(--muted);max-width:640px;
  margin:0 auto 36px;position:relative}
.btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;position:relative}
.btn{padding:14px 28px;border-radius:11px;font-weight:600;font-size:15px;
  transition:.2s;display:inline-flex;align-items:center;gap:9px}
.btn-primary{background:var(--accent);color:#04110c}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 10px 30px rgba(0,209,143,.3)}
.btn-ghost{border:1px solid var(--border);background:var(--bg-soft)}
.btn-ghost:hover{border-color:var(--muted)}

/* STATS */
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;
  background:var(--border);border:1px solid var(--border);
  border-radius:var(--radius);overflow:hidden;margin-top:70px}
.stat{background:var(--bg-soft);padding:32px 20px;text-align:center}
.stat b{display:block;font-size:clamp(26px,4vw,36px);font-weight:800;letter-spacing:-1px}
.stat span{font-size:13px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px}
@media(max-width:640px){.stats{grid-template-columns:1fr}}

/* SECTIONS */
section{padding:80px 0}
.sec-head{text-align:center;max-width:620px;margin:0 auto 54px}
.sec-head h2{font-size:clamp(26px,4vw,38px);letter-spacing:-1px;font-weight:800;margin-bottom:14px}
.sec-head p{color:var(--muted);font-size:16px}

.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}
.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);
  padding:30px 26px;transition:.25s}
.card:hover{transform:translateY(-4px);border-color:rgba(0,209,143,.4)}
.ico{width:44px;height:44px;border-radius:11px;margin-bottom:18px;
  background:rgba(0,209,143,.12);display:grid;place-items:center;
  font-size:20px;color:var(--accent)}
.card h3{font-size:17px;margin-bottom:9px;font-weight:700}
.card p{font-size:14.5px;color:var(--muted)}

.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:28px;counter-reset:s}
.step{position:relative;padding-top:18px}
.step::before{counter-increment:s;content:counter(s);font-size:52px;font-weight:800;line-height:1;
  background:linear-gradient(180deg,var(--accent),transparent);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  display:block;margin-bottom:8px}
.step h3{font-size:17px;margin-bottom:8px}
.step p{font-size:14.5px;color:var(--muted)}

.halving{background:linear-gradient(135deg,rgba(0,209,143,.08),rgba(59,130,246,.08));
  border:1px solid var(--border);border-radius:20px;padding:50px 30px;text-align:center}
.halving h2{font-size:clamp(22px,3.5vw,30px);margin-bottom:8px;letter-spacing:-.6px}
.halving .sub{color:var(--muted);font-size:14px;margin-bottom:28px}
.timer{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
.tbox{background:var(--bg);border:1px solid var(--border);border-radius:12px;
  padding:18px 22px;min-width:92px}
.tbox b{display:block;font-size:30px;font-weight:800;letter-spacing:-1px;
  font-variant-numeric:tabular-nums}
.tbox span{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px}
.halving .note{margin-top:24px;font-size:13px;color:var(--muted)}

.cta{text-align:center;background:var(--bg-soft);border:1px solid var(--border);
  border-radius:20px;padding:60px 30px}
.cta h2{font-size:clamp(24px,4vw,34px);letter-spacing:-1px;margin-bottom:14px}
.cta p{color:var(--muted);max-width:520px;margin:0 auto 30px}

/* FAQ */
details.faq{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);
  padding:0 22px;margin-bottom:12px}
details.faq summary{cursor:pointer;padding:20px 0;font-weight:600;font-size:16px;list-style:none;
  display:flex;justify-content:space-between;align-items:center;gap:14px}
details.faq summary::-webkit-details-marker{display:none}
details.faq summary::after{content:"+";color:var(--accent);font-size:22px;line-height:1;transition:.2s}
details.faq[open] summary::after{transform:rotate(45deg)}
details.faq p{padding:0 0 20px;color:var(--muted);font-size:14.5px}

footer{border-top:1px solid var(--border);padding:44px 0 34px;font-size:13.5px;color:var(--muted)}
.foot{display:flex;justify-content:space-between;gap:26px;flex-wrap:wrap;align-items:center}
.foot-links{display:flex;gap:22px;flex-wrap:wrap}
.foot-links a:hover{color:var(--text)}
.disclaimer{margin-top:26px;padding-top:22px;border-top:1px solid var(--border);
  font-size:12.5px;line-height:1.7}

