/* ============================================================
   LANGUAGE METADATA
   ============================================================ */
const LANGS = {
  en:{flag:"🇬🇧",label:"EN",html:"en",url:"https://ratescout.ru/en/"},
  es:{flag:"🇪🇸",label:"ES",html:"es",url:"https://ratescout.oc.com.ar/"},
  fr:{flag:"🇫🇷",label:"FR",html:"fr",url:"https://ratescout.info.gf/"},
  ru:{flag:"🇷🇺",label:"RU",html:"ru",url:"https://ratescout.ru/"}
};

/* ============================================================
   LINK LOCALIZATION — подставляет URL по языку
   ============================================================ */
function updateLinks(lang){
  const map = LANGS[lang] || LANGS.en;

  // Logo + CTA → языковая версия
  document.querySelectorAll("[data-link='logo']").forEach(a => a.href = map.url);
  document.querySelectorAll("[data-link='cta']").forEach(a => a.href = map.url);

  // Ссылки в футере — всегда ведут на соответствующие языковые версии
  document.querySelectorAll("[data-link^='lang-']").forEach(a => {
    const target = a.getAttribute("data-link").replace("lang-","");
    if(LANGS[target]) a.href = LANGS[target].url;
  });
}

/* ============================================================
   APPLY LANGUAGE
   ============================================================ */
function applyLang(lang){
  if(!I18N[lang]) lang = "en";
  const dict = I18N[lang];

  // 1. Локализуем ссылки
  updateLinks(lang);

  // 2. html lang + title
  document.documentElement.lang = LANGS[lang].html;
  document.title = lang === "en"
    ? "RateScout — Free Crypto & Cash Exchange Rates Directory | 330 Currencies"
    : dict["hero.title1"] + " " + dict["hero.title2"] + " — RateScout";

  // 3. Meta description
  const metaDesc = document.querySelector('meta[name="description"]');
  if(metaDesc) metaDesc.setAttribute("content", dict["hero.sub"]);

  // 4. OG / Twitter
  const ogTitle = document.querySelector('meta[property="og:title"]');
  if(ogTitle) ogTitle.setAttribute("content", document.title);
  const ogDesc = document.querySelector('meta[property="og:description"]');
  if(ogDesc) ogDesc.setAttribute("content", dict["hero.sub"]);
  const ogUrl = document.querySelector('meta[property="og:url"]');
  if(ogUrl) ogUrl.setAttribute("content", LANGS[lang].url);
  const ogLocale = document.querySelector('meta[property="og:locale"]');
  if(ogLocale) ogLocale.setAttribute("content", LANGS[lang].html + "_" + LANGS[lang].html.toUpperCase());
  const twTitle = document.querySelector('meta[name="twitter:title"]');
  if(twTitle) twTitle.setAttribute("content", document.title);
  const twDesc = document.querySelector('meta[name="twitter:description"]');
  if(twDesc) twDesc.setAttribute("content", dict["hero.sub"]);

  // 5. Canonical → языковой URL
  const canonical = document.querySelector('link[rel="canonical"]');
  if(canonical) canonical.setAttribute("href", LANGS[lang].url);

  // 6. Все тексты
  document.querySelectorAll("[data-i18n]").forEach(el => {
    const key = el.getAttribute("data-i18n");
    if(dict[key]) el.textContent = dict[key];
  });

  // 7. Кнопка языка + меню
  document.getElementById("lang-flag").textContent = LANGS[lang].flag;
  document.getElementById("lang-label").textContent = LANGS[lang].label;
  document.querySelectorAll(".lang-menu button").forEach(b => {
    b.setAttribute("aria-current", b.dataset.lang === lang ? "true" : "false");
  });

  // 8. Сохранение + ?lang= в URL (без перезагрузки)
  try{ localStorage.setItem("rs_lang", lang); }catch(e){}
  const url = new URL(window.location.href);
  if(lang === "en") url.searchParams.delete("lang");
  else url.searchParams.set("lang", lang);
  history.replaceState(null, "", url.toString());
}

/* ============================================================
   INIT LANGUAGE
   ============================================================ */
(function initLang(){
  const params = new URLSearchParams(window.location.search);
  const fromUrl = params.get("lang");
  let saved = null;
  try{ saved = localStorage.getItem("rs_lang"); }catch(e){}
  const htmlLang = (document.documentElement.lang || "en").slice(0,2);
  const initial = [fromUrl, saved, htmlLang].find(l => l && I18N[l]) || "en";
  applyLang(initial);
})();

/* ============================================================
   LANGUAGE DROPDOWN
   ============================================================ */
const langWrap = document.getElementById("lang");
const langBtn = langWrap.querySelector(".lang-btn");
langBtn.addEventListener("click", e => {
  e.stopPropagation();
  const open = langWrap.classList.toggle("open");
  langBtn.setAttribute("aria-expanded", open ? "true" : "false");
});
langWrap.querySelectorAll(".lang-menu button").forEach(btn => {
  btn.addEventListener("click", () => {
    applyLang(btn.dataset.lang);
    langWrap.classList.remove("open");
    langBtn.setAttribute("aria-expanded","false");
  });
});
document.addEventListener("click", () => {
  langWrap.classList.remove("open");
  langBtn.setAttribute("aria-expanded","false");
});
document.addEventListener("keydown", e => {
  if(e.key === "Escape"){
    langWrap.classList.remove("open");
    langBtn.setAttribute("aria-expanded","false");
  }
});

/* ============================================================
   HALVING TIMER
   ============================================================ */
(function(){
  const target = new Date("2028-04-15T00:00:00Z").getTime();
  const el = {
    d:document.getElementById("d"),
    h:document.getElementById("h"),
    m:document.getElementById("m"),
    s:document.getElementById("s")
  };
  function tick(){
    const diff = Math.max(0, target - Date.now());
    el.d.textContent = Math.floor(diff/86400000);
    el.h.textContent = String(Math.floor(diff%86400000/3600000)).padStart(2,"0");
    el.m.textContent = String(Math.floor(diff%3600000/60000)).padStart(2,"0");
    el.s.textContent = String(Math.floor(diff%60000/1000)).padStart(2,"0");
  }
  tick(); setInterval(tick,1000);
})();
